{
  "items": [
    {
      "name": "Set.Finite.of_finite_fibers",
      "module_name": "Mathlib.Data.Set.Finite.Lattice",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} (f : α → β) {s : Set α}, (f '' s).Finite → (∀ x ∈ f '' s, (s ∩ f ⁻¹' {x}).Finite) → s.Finite"
    },
    {
      "name": "AlgebraicGeometry.IsFinite.finite_preimage_singleton",
      "module_name": "Mathlib.AlgebraicGeometry.Fiber",
      "kind": "theorem",
      "type": "∀ {X Y : AlgebraicGeometry.Scheme} (f : X ⟶ Y) [AlgebraicGeometry.IsFinite f] (y : ↥Y),\n  (⇑(CategoryTheory.ConcreteCategory.hom f.base) ⁻¹' {y}).Finite"
    },
    {
      "name": "Set.fintypeOfFintypeImage",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "definition",
      "type": "{α : Type u} →\n  {β : Type v} →\n    (s : Set α) → {f : α → β} → {g : β → Option α} → Function.IsPartialInv f g → [Fintype ↑(f '' s)] → Fintype ↑s"
    },
    {
      "name": "Finite.Set.finite_of_finite_image",
      "module_name": "Mathlib.Data.Finite.Set",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} (s : Set α) {f : α → β}, Set.InjOn f s → ∀ [Finite ↑(f '' s)], Finite ↑s"
    },
    {
      "name": "Finite.Set.finite_range",
      "module_name": "Mathlib.Data.Set.Finite.Range",
      "kind": "instance",
      "type": "∀ {α : Type u} {ι : Sort w} (f : ι → α) [Finite ι], Finite ↑(Set.range f)"
    },
    {
      "name": "Set.Finite.preimage'",
      "module_name": "Mathlib.Data.Set.Finite.Lattice",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {f : α → β} {s : Set β}, s.Finite → (∀ b ∈ s, (f ⁻¹' {b}).Finite) → (f ⁻¹' s).Finite"
    }
  ]
}
